// III. THE FINANCIAL OPERATING SYSTEM (FinOS) KERNEL
// ================================================================================================

class FinOSKernel {
    private static instance: FinOSKernel;
    private processTable: Map<FDU_Types.ProcessID, FDU_Types.Process> = new Map();
    private nextPid: FDU_Types.ProcessID = 1;
    private systemTime: FDU_Types.Timestamp = Date.now();
    private bootTime: FDU_Types.Timestamp = Date.now();
    private running: boolean = false;
    private systemCallHandlers: Record<string, Function> = {};
    private worldState: Map<string, any> = new Map();
    private ledger: FDU_Types.StateNode[] = [];
    private cryptoProvider: CryptoProvider;

    private constructor() {
        this.cryptoProvider = new CryptoProvider();
        this.worldState.set('genesis', { message: 'Universe Initialized' });
        const genesisNode: FDU_Types.StateNode = {
            hash: this.cryptoProvider.hash(JSON.stringify({ index: 0 })),
            parentHash: '0'.repeat(64) as FDU_Types.Hash,
            timestamp: this.bootTime,
            transactions: [],
            stateRoot: this.cryptoProvider.hash(JSON.stringify(Object.fromEntries(this.worldState))),
        };
        this.ledger.push(genesisNode);
        this.registerSystemCalls();
        console.log("FinOS Kernel: Initialized.");
    }

    public static getInstance(): FinOSKernel {
        if (!FinOSKernel.instance) {
            FinOSKernel.instance = new FinOSKernel();
        }
        return FinOSKernel.instance;
    }

    public boot(): void {
        if (this.running) return;
        this.running = true;
        console.log(`FinOS Kernel: Boot sequence started at ${new Date(this.bootTime).toISOString()}`);
        // Simulate kernel event loop
        setInterval(() => {
            this.systemTime = Date.now();
            this.scheduleProcesses();
        }, 1000);
        console.log("FinOS Kernel: Boot sequence complete. System is running.");
    }

    public shutdown(): void {
        this.running = false;
        console.log("FinOS Kernel: Shutdown sequence initiated.");
    }

    public createProcess(owner: FDU_Types.UserIdentity['id'], executable: string, parentPid: FDU_Types.ProcessID | null = null): FDU_Types.Process {
        const pid = this.nextPid++;
        const newProcess: FDU_Types.Process = {
            pid,
            parentPid,
            owner,
            status: 'running',
            memoryUsage: Math.floor(Math.random() * 1024) + 128, // Random initial memory
            cpuTime: 0,
            createdAt: Date.now(),
            executable,
        };
        this.processTable.set(pid, newProcess);
        console.log(`FinOS: Process ${pid} (${executable}) created for user ${owner}.`);
        return newProcess;
    }

    public killProcess(pid: FDU_Types.ProcessID): boolean {
        const process = this.processTable.get(pid);
        if (process) {
            process.status = 'stopped';
            console.log(`FinOS: Process ${pid} (${process.executable}) terminated.`);
            // In a real OS, we'd clean up resources here.
            return true;
        }
        return false;
    }

    public listProcesses(): FDU_Types.Process[] {
        return Array.from(this.processTable.values());
    }

    private scheduleProcesses(): void {
        // A very simple scheduler
        this.processTable.forEach(proc => {
            if (proc.status === 'running') {
                proc.cpuTime += Math.random() * 100; // Simulate CPU usage
            }
        });
    }

    private registerSystemCalls(): void {
        this.systemCallHandlers['crypto.sign'] = this.cryptoProvider.sign.bind(this.cryptoProvider);
        this.systemCallHandlers['crypto.verify'] = this.cryptoProvider.verify.bind(this.cryptoProvider);
        this.systemCallHandlers['crypto.hash'] = this.cryptoProvider.hash.bind(this.cryptoProvider);
        this.systemCallHandlers['state.get'] = (key: string) => this.worldState.get(key);
        this.systemCallHandlers['state.set'] = (key: string, value: any) => this.worldState.set(key, value);
        this.systemCallHandlers['ledger.commit'] = (transactions: FDU_Types.Transaction[]) => this.commitToLedger(transactions);
        this.systemCallHandlers['net.request'] = ApiFederation.getInstance().handleRequest.bind(ApiFederation.getInstance());
    }

    public systemCall(call: string, ...args: any[]): any {
        if (!this.running) throw new Error("FinOS Kernel is not running.");
        const handler = this.systemCallHandlers[call];
        if (!handler) {
            throw new Error(`System call not found: ${call}`);
        }
        // In a real OS, we'd have security checks here based on the calling process.
        return handler(...args);
    }

    private commitToLedger(transactions: FDU_Types.Transaction[]): FDU_Types.StateNode {
        // Apply transactions to world state (simplified)
        transactions.forEach(tx => {
            this.worldState.set(`tx_${tx.id}`, tx);
        });

        const parentNode = this.ledger[this.ledger.length - 1];
        const newNode: FDU_Types.StateNode = {
            hash: this.cryptoProvider.hash(JSON.stringify({ index: this.ledger.length, transactions })),
            parentHash: parentNode.hash,
            timestamp: Date.now(),
            transactions,
            stateRoot: this.cryptoProvider.hash(JSON.stringify(Object.fromEntries(this.worldState))),
        };
        this.ledger.push(newNode);
        console.log(`FinOS: Committed new block ${newNode.hash} to the ledger with ${transactions.length} transactions.`);
        return newNode;
    }
}

class CryptoProvider {
    // Mock crypto functions for simulation purposes.
    public generateKeyPair(): FDU_Types.KeyPair {
        const privateKey = `0x${this.randomHex(64)}`;
        const publicKey = `0x${this.randomHex(64)}`;
        return { privateKey, publicKey, algorithm: 'ECDSA' };
    }

    public sign(data: string, privateKey: FDU_Types.PrivateKey): FDU_Types.Signature {
        return `0x${this.hash(data + privateKey).slice(7)}`;
    }

    public verify(data: string, signature: FDU_Types.Signature, publicKey: FDU_Types.PublicKey): boolean {
        // This is a highly simplified verification for simulation.
        return signature === `0x${this.hash(data + `0x${publicKey.slice(2)}`).slice(7)}`;
    }

    public hash(data: string): FDU_Types.Hash {
        // Simple SHA256-like hash simulation
        let hash = 0;
        for (let i = 0; i < data.length; i++) {
            const char = data.charCodeAt(i);
            hash = ((hash << 5) - hash) + char;
            hash |= 0; // Convert to 32bit integer
        }
        const hexHash = (hash >>> 0).toString(16).padStart(8, '0').repeat(8);
        return `sha256:${hexHash}`;
    }

    private randomHex(length: number): string {
        return [...Array(length)].map(() => Math.floor(Math.random() * 16).toString(16)).join('');
    }
}

