// IV. DEMOCRA-UI: THE SELF-CONTAINED RENDERING ENGINE
// ================================================================================================

namespace DemocraUI {
    let currentRoot: HTMLElement | null = null;
    let currentVNode: FDU_Types.VNode | null = null;
    let stateHooks: any[] = [];
    let stateHookIndex = 0;

    function createElement(
        type: FDU_Types.VNodeType,
        props: Record<string, any> = {},
        ...children: (FDU_Types.VNode | string)[]
    ): FDU_Types.VNode {
        return {
            type,
            props: {
                ...props,
                children: children.flat().map(child =>
                    typeof child === 'object' && child !== null ? child : createTextElement(String(child))
                ),
            },
        };
    }

    function createTextElement(text: string): FDU_Types.VNode {
        return {
            type: "TEXT_ELEMENT",
            props: { nodeValue: text, children: [] },
        };
    }

    function render(vnode: FDU_Types.VNode, container: HTMLElement) {
        currentRoot = container;
        currentVNode = vnode;
        diff(container, vnode, undefined);
    }

    function diff(parentDom: HTMLElement, newVNode?: FDU_Types.VNode, oldVNode?: FDU_Types.VNode, index = 0) {
        if (!newVNode && oldVNode) {
            oldVNode.dom?.remove();
            return;
        }

        if (newVNode && !oldVNode) {
            const newDom = createDom(newVNode);
            parentDom.appendChild(newDom);
            return;
        }

        if (newVNode && oldVNode) {
            if (newVNode.type !== oldVNode.type) {
                const newDom = createDom(newVNode);
                parentDom.replaceChild(newDom, oldVNode.dom!);
                return;
            }

            const dom = (newVNode.dom = oldVNode.dom!);

            if (newVNode.type === "TEXT_ELEMENT") {
                if (newVNode.props.nodeValue !== oldVNode.props.nodeValue) {
                    dom.textContent = newVNode.props.nodeValue;
                }
                return;
            }

            updateDom(dom as HTMLElement, oldVNode.props, newVNode.props);

            const oldChildren = oldVNode.props.children || [];
            const newChildren = newVNode.props.children || [];
            const len = Math.max(oldChildren.length, newChildren.length);

            for (let i = 0; i < len; i++) {
                diff(dom as HTMLElement, newChildren[i], oldChildren[i], i);
            }
        }
    }

    const isEvent = (key: string) => key.startsWith("on");
    const isProperty = (key: string) => key !== "children" && !isEvent(key);
    const isNew = (prev: any, next: any) => (key: string) => prev[key] !== next[key];
    const isGone = (prev: any, next: any) => (key: string) => !(key in next);

    function updateDom(dom: HTMLElement, prevProps: any, nextProps: any) {
        // Remove old or changed event listeners
        Object.keys(prevProps)
            .filter(isEvent)
            .filter(key => !(key in nextProps) || isNew(prevProps, nextProps)(key))
            .forEach(name => {
                const eventType = name.toLowerCase().substring(2);
                dom.removeEventListener(eventType, prevProps[name]);
            });

        // Remove old properties
        Object.keys(prevProps)
            .filter(isProperty)
            .filter(isGone(prevProps, nextProps))
            .forEach(name => {
                (dom as any)[name] = "";
            });

        // Set new or changed properties
        Object.keys(nextProps)
            .filter(isProperty)
            .filter(isNew(prevProps, nextProps))
            .forEach(name => {
                if (name === 'className') {
                    dom.setAttribute('class', nextProps[name]);
                } else {
                    (dom as any)[name] = nextProps[name];
                }
            });

        // Add event listeners
        Object.keys(nextProps)
            .filter(isEvent)
            .filter(isNew(prevProps, nextProps))
            .forEach(name => {
                const eventType = name.toLowerCase().substring(2);
                dom.addEventListener(eventType, nextProps[name]);
            });
    }

    function createDom(vnode: FDU_Types.VNode): HTMLElement | Text {
        if (typeof vnode.type === 'function') {
            stateHookIndex = 0;
            stateHooks = [];
            const componentVNode = vnode.type(vnode.props);
            const dom = createDom(componentVNode);
            vnode.dom = dom;
            return dom;
        }

        const dom =
            vnode.type === "TEXT_ELEMENT"
                ? document.createTextNode("")
                : document.createElement(vnode.type as string);

        updateDom(dom as HTMLElement, {}, vnode.props);

        vnode.props.children?.forEach(child => {
            if (typeof child !== 'string') {
                (dom as HTMLElement).appendChild(createDom(child));
            }
        });

        vnode.dom = dom;
        return dom;
    }

    export function useState<T>(initialState: T): [T, FDU_Types.StateSetter<T>] {
        const currentIndex = stateHookIndex;
        const oldHook = stateHooks[currentIndex];
        const hook = {
            state: oldHook ? oldHook.state : initialState,
            queue: oldHook ? oldHook.queue : [],
        };

        hook.queue.forEach((action: any) => {
            hook.state = typeof action === 'function' ? action(hook.state) : action;
        });
        hook.queue = [];

        stateHooks[currentIndex] = hook;
        stateHookIndex++;

        const setState: FDU_Types.StateSetter<T> = action => {
            hook.queue.push(action);
            // Re-render the whole tree on state change
            if (currentRoot && currentVNode) {
                stateHookIndex = 0;
                const newVNode = currentVNode.type(currentVNode.props);
                diff(currentRoot, newVNode, currentVNode);
                currentVNode = newVNode;
            }
        };

        return [hook.state, setState];
    }

    // Re-implementation of original components using DemocraUI
    export const Card: FDU_Types.VNodeComponent = ({ title, children }) => {
        return createElement(
            'div',
            { className: 'bg-gray-800/50 border border-gray-700 rounded-lg p-6 shadow-lg' },
            createElement('h3', { className: 'text-xl font-bold text-cyan-400 mb-4' }, title),
            createElement('div', { className: 'space-y-4' }, ...children)
        );
    };

    export const PlaidLinkButton: FDU_Types.VNodeComponent = ({ onSuccess, products = ['transactions', 'auth'] }) => {
        const [isLoading, setIsLoading] = useState(false);
        const plaidService = PlaidIntegrationService.getInstance();

        const handleClick = async () => {
            setIsLoading(true);
            try {
                const { link_token } = await plaidService.createLinkToken('user-123', products, ['US']);
                // In a real scenario, this would open the Plaid Link modal.
                // Here, we simulate a successful link after a delay.
                console.log(`DemocraUI: PlaidLink initiated with token: ${link_token}`);
                setTimeout(() => {
                    const mockMetadata: FDU_Types.PlaidLinkSuccessMetadata = {
                        institution: { name: 'First Democratic Bank', institution_id: 'ins_123' },
                        accounts: [
                            { id: 'acc_1', name: 'Democracy Checking', mask: '1111', type: 'depository', subtype: 'checking' },
                            { id: 'acc_2', name: 'Freedom Savings', mask: '2222', type: 'depository', subtype: 'savings' },
                        ],
                        link_session_id: `session_${Date.now()}`,
                    };
                    onSuccess(`public-token-${Date.now()}`, mockMetadata);
                    setIsLoading(false);
                }, 2000);
            } catch (error) {
                console.error("PlaidLink failed:", error);
                setIsLoading(false);
            }
        };

        return createElement(
            'button',
            {
                className: `w-full px-4 py-2 font-semibold text-white bg-cyan-600 rounded-md hover:bg-cyan-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-gray-900 focus:ring-cyan-500 disabled:bg-gray-500`,
                onClick: handleClick,
                disabled: isLoading,
            },
            isLoading ? 'Connecting...' : 'Connect a Bank Account'
        );
    };
}

