// VI. MOCKED PLAID INTEGRATION SERVICE (FROM ORIGINAL FILE, ADAPTED)
// ================================================================================================

class PlaidIntegrationService {
    private static instance: PlaidIntegrationService;
    private kernel: FinOSKernel = FinOSKernel.getInstance();

    private constructor() {}

    public static getInstance(): PlaidIntegrationService {
        if (!PlaidIntegrationService.instance) {
            PlaidIntegrationService.instance = new PlaidIntegrationService();
        }
        return PlaidIntegrationService.instance;
    }

    public async createLinkToken(userId: string, products: FDU_Types.PlaidProduct[], countryCodes: string[]): Promise<{ link_token: string }> {
        console.log(`[SIM] PlaidService: Requesting link token for user ${userId} via FinOS`);
        return new Promise(resolve => {
            setTimeout(() => {
                const token = `link-sandbox-${Date.now()}`;
                this.kernel.systemCall('state.set', `plaid_link_token_${token}`, { userId, products, countryCodes, status: 'pending' });
                resolve({ link_token: token });
            }, 500);
        });
    }

    public async exchangePublicToken(publicToken: string, metadata: FDU_Types.PlaidLinkSuccessMetadata): Promise<FDU_Types.LinkedInstitution> {
        console.log(`[SIM] PlaidService: Exchanging public token: ${publicToken} via FinOS`);
        return new Promise(resolve => {
            setTimeout(() => {
                const now = new Date();
                const accounts = metadata.accounts.map(acc => ({
                    id: acc.id,
                    institutionId: metadata.institution.institution_id,
                    name: acc.name,
                    mask: acc.mask,
                    type: acc.type,
                    subtype: acc.subtype,
                }));

                const newInstitution: FDU_Types.LinkedInstitution = {
                    id: `item-${Date.now()}`,
                    name: metadata.institution.name,
                    institutionId: metadata.institution.institution_id,
                    connectedAccounts: accounts,
                    metadata: metadata,
                    lastUpdated: now,
                    status: 'connected',
                };

                const transaction: FDU_Types.Transaction = {
                    id: `tx_${Date.now()}`,
                    from: '0xSYSTEM',
                    to: '0xUSER123',
                    amount: '0',
                    asset: 'LINKED_INSTITUTION',
                    nonce: 0,
                    signature: '0xSIGNED',
                    metadata: { action: 'link_institution', institution: newInstitution },
                };
                this.kernel.systemCall('ledger.commit', [transaction]);

                resolve(newInstitution);
            }, 1000);
        });
    }
}

