    document.head.appendChild(style);

    const rootElement = document.getElementById('root');
    if (!rootElement) {
        console.error('Root element not found. Cannot boot universe.');
        return;
    }

    console.log("Bootstrapping Financial Democracy Universe...");

    // 1. Boot the Kernel
    const kernel = FinOSKernel.getInstance();
    kernel.boot();

    // 2. Initialize the API Federation
    ApiFederation.getInstance();

    // 3. Create the root user and process
    const rootUser: FDU_Types.UserIdentity = {
        id: 'user-root',
        publicKey: '0xROOT',
        username: 'root',
        credentials: [],
        permissions: ['*'],
    };
    kernel.createProcess(rootUser.id, '/bin/init');

    // 4. Render the main application using DemocraUI
    DemocraUI.render(DemocraUI.createElement(FinancialDemocracyView, {}), rootElement);

    console.log("Universe bootstrap complete. Welcome to the revolution.");
