// Self-executing call to bootstrap when the script is loaded.
// In a real module system, this would be an exported function.
if (typeof document !== 'undefined') {
    document.addEventListener('DOMContentLoaded', bootstrapUniverse);
}

// Export a namespace to prevent global scope pollution, while allowing access if needed.
export const FinancialDemocracyUniverse = {
    FinOSKernel,
    DemocraUI,
    ApiFederation,
    PlaidIntegrationService,
    bootstrap: bootstrapUniverse,
};